function toast(message, error=false) {
  let box=$('#toastContainer'); if(!box){box=document.createElement('div');box.id='toastContainer';box.className='toast-container';document.body.append(box);}
  const item=document.createElement('div'); item.className=`toast${error?' error':''}`; item.textContent=message; box.append(item); setTimeout(()=>item.remove(),4200);
}
function when(value) { const d=value?.toDate?value.toDate():value instanceof Date?value:new Date(value||0); return Number.isNaN(d.getTime())?'—':d.toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'}); }
function rel(path){return collection(db,'users',state.user.uid,path);}
function applyTheme(theme='dark') {
  const resolved=theme==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):theme;
  document.documentElement.dataset.theme=resolved;
  document.documentElement.style.colorScheme=resolved;
  document.documentElement.classList.toggle('reduce-motion',!!state.prefs.reducedMotion);
  const meta=$('meta[name="theme-color"]'); if(meta) meta.content=resolved==='light'?'#f3f5fb':'#090b13';
}
async function loadCollection(name, cap=100) {
  const sortField=['scans','reports','notifications'].includes(name)?'createdAt':'updatedAt';
  const q=query(rel(name),orderBy(sortField,'desc'),limit(cap));let snap;try{snap=await getDocs(q);}catch(error){try{snap=await getDocsFromCache(q);}catch{if(!navigator.onLine||error?.code==='unavailable')return [];throw error;}}return snap.docs.map(d=>({id:d.id,...d.data()}));
}
async function loadState(user) {
  if(!user || state.user?.uid!==user.uid) return;
  const [projects,assets,legacyDomains,reports,notifications,scans,prefSnap]=await Promise.all([
    loadCollection('projects'),loadCollection('assets'),loadCollection('domains'),loadCollection('reports'),loadCollection('notifications'),loadCollection('scans'),getDoc(doc(db,'users',user.uid,'preferences','main')).catch(()=>getDocFromCache(doc(db,'users',user.uid,'preferences','main')).catch(()=>null))
  ]);
  if(state.user?.uid!==user.uid) return;
  state.projects=projects.sort((a,b)=>dateNum(b.updatedAt)-dateNum(a.updatedAt));
  state.assets=assets.sort((a,b)=>dateNum(b.updatedAt)-dateNum(a.updatedAt));
  state.legacyDomains=legacyDomains;
  state.reports=reports.sort((a,b)=>dateNum(b.createdAt)-dateNum(a.createdAt));
  state.notifications=notifications.sort((a,b)=>dateNum(b.createdAt)-dateNum(a.createdAt));
  state.scans=scans.sort((a,b)=>dateNum(b.createdAt)-dateNum(a.createdAt));
  if(prefSnap.exists()) state.prefs={...state.prefs,...prefSnap.data()};
  applyTheme(state.prefs.theme); renderAll();
}
function dateNum(v){const d=v?.toDate?v.toDate():new Date(v||0);return d.getTime()||0;}
async function fetchJsonV3(url, timeoutMs=14000){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeoutMs);try{const response=await fetch(url,{signal:controller.signal,headers:{accept:'application/json'}});if(!response.ok)throw Error(`HTTP ${response.status}`);return await response.json();}catch(error){if(error.name==='AbortError')throw Error('Публичный источник не ответил вовремя.');if(error instanceof TypeError)throw Error('Источник недоступен из браузера (сеть или CORS).');throw error;}finally{clearTimeout(timer);}}
function pageShell(id, eyebrow, title, desc, content) {
  return `<section class="page-panel v3-page" id="page-${id}"><div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${content}</section>`;
}
